if(typeof importScripts==='function')importScripts('i18n-messages.js?v=114','official-names.js?v=113','i18n.js?v=113');
/* Login pages and navigations are never cached. App assets contain no user data. */
const CACHE='disney-assets-v114',BUILD='114';const ASSETS=['startup.js','manifest-de.webmanifest','manifest-en.webmanifest','manifest-fr.webmanifest','manifest-it.webmanifest','manifest-es.webmanifest','manifest-zh-Hans.webmanifest','manifest-ja.webmanifest','manifest-ko.webmanifest','manifest-ar.webmanifest','i18n.js','i18n-messages.js','official-names.js','restaurant-search.js','restaurant-ratings.js','map-diagnostics.js','map-3d.js','park-models.js','park-scene.json','vendor/maplibre-gl.css','vendor/maplibre-gl.mjs','vendor/maplibre-gl-shared.mjs','vendor/maplibre-gl-worker.mjs','swipe-list.js','chart-interaction.js','preferences.js','surfaces.js','vendor/leaflet.js','vendor/leaflet-rotate.js','vendor/leaflet.css','style.css','app.js','disney-guide.js','queue-dwell.js','routing.js','wait-times.js','show-times.js','child-access.js','ratings.js','push-client.js','route-worker.js','park-data.json','disney-original.png','icon-192.png','icon-512.png','icon.svg','manifest.webmanifest'];
const ASSET_SCOPE=self.location.origin==='https://abetterdisneylandparisapp.weletapi.com'?new URL('App/',self.registration.scope).href:self.registration.scope;
self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);for(const file of ASSETS){try{const response=await fetch(new URL(file+(/\.(js|css)$/.test(file)?'?v='+BUILD:''),ASSET_SCOPE),{redirect:'error',cache:'reload'});if(response.ok&&response.headers.get('content-type')?.includes('text/html')!==true)await cache.put(new URL(file+(/\.(js|css)$/.test(file)?'?v='+BUILD:''),ASSET_SCOPE),response);}catch{}}await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('disney-assets-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();})());});
const LANGUAGE_KEY='disney-language-preference';
async function savedLanguage(){try{const stored=await(await caches.open(CACHE)).match(LANGUAGE_KEY);return stored?await stored.text():'en';}catch{return 'en';}}
self.addEventListener('message',event=>{if(event.data?.type==='disney-language'&&typeof DisneyI18n!=='undefined')event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.put(LANGUAGE_KEY,new Response(DisneyI18n.resolve(event.data.language)));})());});
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(u.origin!==self.location.origin||!u.pathname.startsWith(new URL(self.registration.scope).pathname)||event.request.method!=='GET')return;if(event.request.mode==='navigate'){event.respondWith(fetch(event.request).catch(async()=>{const lang=await savedLanguage(),localize=value=>typeof DisneyI18n==='undefined'?value:DisneyI18n.html(value,lang);return new Response(localize('<!doctype html><html lang="de"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Disney · Verbindung nötig</title><body style="font-family:system-ui;padding:32px;color:#192f68"><h1>Du bist offline</h1><p>Zum Öffnen der App wird eine Verbindung benötigt. Eine bereits geöffnete Route funktioniert auch ohne Netz.</p><form><button type="submit" style="padding:14px;font:inherit">Erneut versuchen</button></form></body></html>'.replace('Zum Öffnen der App wird eine Verbindung benötigt. Eine bereits geöffnete Route funktioniert auch ohne Netz.',self.location.origin==='https://abetterdisneylandparisapp.weletapi.com'?'Zum Öffnen der App wird eine Verbindung benötigt. Eine bereits geöffnete Route funktioniert auch ohne Netz.':'Zum sicheren Öffnen der Disney-App brauchen wir eine Verbindung und deine weletapi-Anmeldung. Eine bereits geöffnete Route funktioniert auch ohne Netz.').replace('lang="de"','lang="'+lang+'" dir="'+(lang==='ar'?'rtl':'ltr')+'"')),{headers:{'Content-Type':'text/html; charset=utf-8'},status:503});}));return;}if(!u.pathname.startsWith(new URL(ASSET_SCOPE).pathname))return;const relative=u.pathname.slice(new URL(ASSET_SCOPE).pathname.length);const photo=/^photos\/[a-f0-9]{16}\.(?:webp|gif)$/.test(relative)&&!u.search;if((photo||ASSETS.includes(relative))&&(!u.search||(u.searchParams.get('v')===BUILD&&[...u.searchParams].length===1)))event.respondWith((async()=>{const cache=await caches.open(CACHE);if(photo||relative==='disney-guide.js'){const hit=await cache.match(event.request);if(hit)return hit;}try{const response=await fetch(event.request,{redirect:'error'});if(response.ok&&response.headers.get('content-type')?.includes('text/html')!==true)await cache.put(event.request,response.clone());return response;}catch{const hit=await caches.match(event.request);return hit||new Response('Offline',{status:503});}})());});

self.addEventListener('push',event=>{event.waitUntil((async()=>{let message={};try{message=event.data?.json()||{};}catch{}const lang=message.language||await savedLanguage(),t=value=>typeof DisneyI18n==='undefined'?value:DisneyI18n.text(value,lang);await self.registration.showNotification(message.title||t('Disney · Neuer Hinweis'),{body:message.body||t('In Disney gibt es einen neuen Hinweis.'),icon:'icon-192.png',badge:'icon-192.png',tag:message.tag||'disney-info',data:{rideId:typeof message.id==='string'?message.id:null,kind:message.kind},renotify:false});})());});
self.addEventListener('notificationclick',event=>{event.notification.close();event.waitUntil((async()=>{const url=new URL('./',ASSET_SCOPE);if(event.notification.data?.kind==='update')url.searchParams.set('view','info');if(event.notification.data?.rideId)url.searchParams.set(event.notification.data.kind==='checkin'?'checkin':'notice',event.notification.data.rideId);const clients=await self.clients.matchAll({type:'window',includeUncontrolled:true});for(const client of clients){if(client.url.startsWith(ASSET_SCOPE)){if(event.notification.data?.rideId){client.postMessage({type:event.notification.data.kind==='checkin'?'disney-open-checkin':'disney-open-notice',id:event.notification.data.rideId});}else{await client.navigate(url.href);}await client.focus();return;}}await self.clients.openWindow(url.href);})());});
